INSERT INTO texts VALUES(10000010,'Drago Alato di Ra',replace(replace('Non può essere Evocato Specialmente. \r\nRichiede 3 Tributi per essere Evocato Normalmente (non può essere Posizionato Normalmente). \r\nL''Evocazione Normale di questa carta non può essere annullata. \r\nQuando viene Evocato Normalmente, non possono essere attivate altre carte o effetti. \r\nQuando questa carta viene Evocata Normalmente: puoi pagare LP fino a che te ne rimangono solo 100; questa carta guadagna ATK/DEF pari all''ammontare di LP pagati. \r\nPuoi pagare 1000 LP, poi scegliere come bersaglio 1 mostro sul Terreno; distruggi quel bersaglio.','\r',char(13)),'\n',char(10)),'Aumentare ATK/DEF','Distruggere','Offri 3 mostri come Tributo per Evocare','','','','','','','','','','','','','');
